#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=7

# 本向导在 WSL 内运行。仓库放 WSL 文件系统；Windows 侧工作区经 /mnt/h 访问。
# WIN_REPO_SRC 为可选本地拷贝源（默认指向已被 gitignore 的旧路径，通常不存在）；
# 不存在时脚本自动 git clone 官方仓库，无需手动准备。
WIN_REPO_SRC="${WIN_REPO_SRC:-/mnt/h/ai-code-llmops/deploy/tencent-memory}"
REPO_DIR="${REPO_DIR:-$HOME/TencentDB-Agent-Memory}"
MEMORY_ENV="$REPO_DIR/deploy/global-images/.env"

banner "腾讯记忆 MemoryCore 自托管部署（WSL + Docker）"

# ── Stage 1: 确认 WSL + Docker 就绪 ───────────────────────────────────────
stage "确认 WSL 与 Docker 引擎"
say "本机 Docker 运行在 WSL2（Ubuntu）内。"
if command -v docker >/dev/null 2>&1 && docker info >/dev/null 2>&1; then
  say "✓ Docker 已就绪：$(docker version --format '{{.Server.Version}}' 2>/dev/null || echo '?')"
else
  warn "WSL 内没有可用的 Docker 引擎。"
  step "在 WSL 终端里执行："
  say "    sudo apt-get update && sudo apt-get install -y docker.io docker-compose-v2"
  say "    sudo systemctl enable --now docker"
  note "装完重跑本向导即可继续（会重新检查）。"
  pause "Docker 就绪后按回车，或 Ctrl-C 退出"
  docker info >/dev/null 2>&1 || { warn "Docker 仍不可用，请先安装"; pause; }
fi

# ── Stage 2: 腾讯仓库（放 WSL 文件系统）───────────────────────────────────
stage "腾讯仓库（TencentDB-Agent-Memory）"
if [[ -f "$REPO_DIR/deploy/global-images/start-all.sh" ]]; then
  say "✓ 仓库已存在 $REPO_DIR"
else
  if [[ -d "$WIN_REPO_SRC/deploy/global-images" ]]; then
    say "从 Windows 侧复制（$WIN_REPO_SRC）→ $REPO_DIR"
    mkdir -p "$(dirname "$REPO_DIR")"
    cp -r "$WIN_REPO_SRC" "$REPO_DIR"
  else
    say "克隆 TencentCloud/TencentDB-Agent-Memory → $REPO_DIR"
    git clone --depth 1 https://github.com/TencentCloud/TencentDB-Agent-Memory "$REPO_DIR"
  fi
fi
[[ -f "$REPO_DIR/deploy/global-images/start-all.sh" ]] || { warn "仓库不完整，请手动检查"; pause; }

# ── Stage 3: 填写 .env（DeepSeek 两组 LLM）────────────────────────────────
stage "填写 .env — DeepSeek 两组 LLM 配置"
ENV_FILE="$MEMORY_ENV"
say "memory 组（embed/summarize）与 proxy 组（用户请求转发）都走 DeepSeek。"
say "API Key 隐藏输入；回车 = 保留已有值。"

ask MEMORY_LLM_BASE_URL "Memory 组 BASE_URL [默认 https://api.deepseek.com/v1]:"
MEMORY_LLM_BASE_URL="${MEMORY_LLM_BASE_URL:-https://api.deepseek.com/v1}"
ask_secret MEMORY_LLM_API_KEY "Memory 组 API Key:"
ask MEMORY_LLM_MODEL "Memory 组 MODEL [默认 deepseek-v4-flash]:"
MEMORY_LLM_MODEL="${MEMORY_LLM_MODEL:-deepseek-v4-flash}"

if confirm "Proxy 组复用 Memory 组配置（同一 DeepSeek key）"; then
  PROXY_UPSTREAM_URL="$MEMORY_LLM_BASE_URL"
  PROXY_UPSTREAM_API_KEY="$MEMORY_LLM_API_KEY"
  PROXY_UPSTREAM_MODEL="$MEMORY_LLM_MODEL"
else
  ask PROXY_UPSTREAM_URL "Proxy 组 UPSTREAM_URL [默认 https://api.deepseek.com/v1]:"
  PROXY_UPSTREAM_URL="${PROXY_UPSTREAM_URL:-https://api.deepseek.com/v1}"
  ask_secret PROXY_UPSTREAM_API_KEY "Proxy 组 UPSTREAM_API_KEY:"
  ask PROXY_UPSTREAM_MODEL "Proxy 组 UPSTREAM_MODEL [默认 deepseek-v4-flash]:"
  PROXY_UPSTREAM_MODEL="${PROXY_UPSTREAM_MODEL:-deepseek-v4-flash}"
fi

write_env MEMORY_LLM_BASE_URL    "$MEMORY_LLM_BASE_URL"
write_env MEMORY_LLM_API_KEY     "$MEMORY_LLM_API_KEY"
write_env MEMORY_LLM_MODEL       "$MEMORY_LLM_MODEL"
write_env MEMORY_LLM_PROTOCOL    "openai"
write_env PROXY_UPSTREAM_URL     "$PROXY_UPSTREAM_URL"
write_env PROXY_UPSTREAM_API_KEY "$PROXY_UPSTREAM_API_KEY"
write_env PROXY_UPSTREAM_MODEL   "$PROXY_UPSTREAM_MODEL"
note "已写入 $MEMORY_ENV（本地网关默认空鉴权 MEMORY_CORE_GATEWAY_API_KEY=空）"

# ── Stage 4: 运行 start-all.sh ────────────────────────────────────────────
stage "启动三件套（memory-core / memory-hub / proxy）"
say "将执行：cd $REPO_DIR/deploy/global-images && ./start-all.sh"
note "脚本自动校验两组 LLM 通路（不消耗 token），再拉起三个容器；"
note "首次会拉取镜像 agentmemory/*:latest，需要几分钟。"
if confirm "现在运行 start-all.sh？"; then
  ( cd "$REPO_DIR/deploy/global-images" && ./start-all.sh )
else
  warn "跳过启动；之后手动执行：cd $REPO_DIR/deploy/global-images && ./start-all.sh"
fi
pause "确认服务已启动后按回车"

# ── Stage 5: 验证服务 ─────────────────────────────────────────────────────
stage "验证服务（Panel / Gateway / Knowledge / Proxy）"
open_url "http://localhost:8125"
step "浏览器打开 Memory Panel（8125）。"
for port in 8125 8420 8424 8096; do
  code=$(curl -s -o /dev/null -w '%{http_code}' --max-time 3 "http://localhost:${port}/" 2>/dev/null || echo "000")
  printf '  %s•%s port %s → HTTP %s\n' "$BLUE" "$RESET" "$port" "$code"
done
docker ps --filter "name=tdai" --format "  {{.Names}}\t{{.Status}}" 2>/dev/null || true
pause "确认 Panel 可打开后按回车"

# ── Stage 6: 对接我们的应用（系统设置）───────────────────────────────────
stage "对接应用：系统设置 → 记忆系统 → 腾讯记忆"
say "收集三项配置（本地网关默认空鉴权，API Key 填任意串即可；SERVICE_ID 为本地占位，联调确认）。"
ask TENCENT_MEMORY_ENDPOINT "endpoint [默认 http://127.0.0.1:8420]:"
TENCENT_MEMORY_ENDPOINT="${TENCENT_MEMORY_ENDPOINT:-http://127.0.0.1:8420}"
ask_secret TENCENT_MEMORY_API_KEY "api_key（本地任意串，如 local）:"
ask TENCENT_MEMORY_SERVICE_ID "service_id（本地占位，建议 local，联调确认）:"
TENCENT_MEMORY_SERVICE_ID="${TENCENT_MEMORY_SERVICE_ID:-local}"
note "提示：WSL2 NAT 模式下 Windows 侧 localhost:8420 通常可直接转发到 WSL；"
note "若应用连不上，改用 WSL IP（WSL 里 ip addr show eth0 查看，如 172.x.x.x）。"

open_url "http://localhost:5173/settings"
step "系统设置 → 记忆系统 tab → 选择「腾讯记忆」→ 粘贴三项并保存："
printf '    %s\n' "$TENCENT_MEMORY_ENDPOINT"
printf '    %s（已隐藏，长度 %s）\n' "${TENCENT_MEMORY_API_KEY:+(masked)}" "${#TENCENT_MEMORY_API_KEY}"
printf '    %s\n' "$TENCENT_MEMORY_SERVICE_ID"
note "保存后后端即时生效（DB > 环境变量 > 默认）。"
pause "保存完成后按回车"

# ── Stage 7: 验证记忆读写 ─────────────────────────────────────────────────
stage "验证记忆读写"
open_url "http://localhost:5173/space/apps"
step "打开任意应用 → 能力 → 长期记忆 → 记忆系统选「腾讯记忆」→ 发几条消息。"
open_url "http://localhost:8125"
step "在 Memory Panel 里确认 L0→L3 分层记忆是否生成/更新。"
note "若 Panel 无数据：docker logs -f tdai-memory-core 排查。"
pause "验证完成后按回车"

finish
